async function request(path, options = {}) {
  const response = await fetch(`/api${path}`, {
    headers: { 'Content-Type': 'application/json', ...(options.headers || {}) },
    ...options
  })
  let payload = null
  try {
    payload = await response.json()
  } catch {
    payload = null
  }
  if (!response.ok) {
    const error = new Error(payload?.error || `Request failed (${response.status})`)
    error.status = response.status
    throw error
  }
  return payload
}

export const api = {
  bootstrap: () => request('/bootstrap'),
  market: params => {
    const query = new URLSearchParams()
    Object.entries(params || {}).forEach(([key, value]) => {
      if (value !== undefined && value !== null && value !== '' && value !== 0 && value !== '0') {
        query.set(key, value)
      }
    })
    return request(`/market?${query.toString()}`)
  },
  buyPlayer: (playerId, teamId) =>
    request('/transfers/buy', {
      method: 'POST',
      body: JSON.stringify({ player_id: playerId, team_id: teamId })
    }),
  upgradeFacility: (teamId, facility) =>
    request('/facilities/upgrade', {
      method: 'POST',
      body: JSON.stringify({ team_id: teamId, facility })
    }),
  updateTactics: (teamId, tactics) =>
    request('/tactics', {
      method: 'POST',
      body: JSON.stringify({ team_id: teamId, ...tactics })
    }),
  simulateMatch: matchId =>
    request(`/matches/${matchId}/simulate`, {
      method: 'POST',
      body: JSON.stringify({})
    }),
  match: matchId => request(`/matches/${matchId}`)
}

export function money(value, { decimals = 1 } = {}) {
  const number = Number(value) || 0
  const sign = number < 0 ? '-' : ''
  const abs = Math.abs(number)
  if (abs >= 1_000_000_000) return `${sign}€${(abs / 1_000_000_000).toFixed(decimals)}B`
  if (abs >= 1_000_000) return `${sign}€${(abs / 1_000_000).toFixed(decimals)}M`
  if (abs >= 1_000) return `${sign}€${Math.round(abs / 1_000)}K`
  return `${sign}€${Math.round(abs)}`
}

export function moneyFull(value) {
  return new Intl.NumberFormat('en-GB', {
    style: 'currency',
    currency: 'EUR',
    maximumFractionDigits: 0
  }).format(Number(value) || 0)
}

export function shortDate(value, { weekday = true } = {}) {
  if (!value) return 'TBC'
  const date = new Date(`${value}T12:00:00Z`)
  if (Number.isNaN(date.getTime())) return 'TBC'
  return new Intl.DateTimeFormat('en-GB', {
    weekday: weekday ? 'short' : undefined,
    day: 'numeric',
    month: 'short'
  }).format(date)
}

export function longDate(value) {
  if (!value) return 'TBC'
  const date = new Date(`${value}T12:00:00Z`)
  return new Intl.DateTimeFormat('en-GB', {
    weekday: 'long',
    day: 'numeric',
    month: 'long',
    year: 'numeric'
  }).format(date)
}

export function isHome(match, teamId) {
  return Number(match?.home_team_id) === Number(teamId)
}

export function opponent(match, teamId) {
  if (!match) return null
  return isHome(match, teamId) ? match.away_team : match.home_team
}

export function resultFor(match, teamId) {
  if (!match || match.status !== 'finished') return null
  const home = isHome(match, teamId)
  const mine = home ? match.home_score : match.away_score
  const theirs = home ? match.away_score : match.home_score
  if (mine > theirs) return 'W'
  if (mine < theirs) return 'L'
  return 'D'
}

export function scoreFor(match, teamId) {
  if (!match || match.status !== 'finished') return null
  return isHome(match, teamId)
    ? `${match.home_score}–${match.away_score}`
    : `${match.away_score}–${match.home_score}`
}

export function initials(name, max = 2) {
  return String(name || '?')
    .split(' ')
    .filter(Boolean)
    .slice(0, max)
    .map(part => part[0])
    .join('')
    .toUpperCase()
}

export function ratingTone(rating) {
  if (rating >= 8) return 'rating-elite'
  if (rating >= 7) return 'rating-good'
  if (rating >= 6) return 'rating-ok'
  return 'rating-poor'
}

export function ratingText(rating) {
  if (rating >= 8.5) return 'text-lime'
  if (rating >= 7.5) return 'text-lime-300'
  if (rating >= 6.5) return 'text-sky-300'
  if (rating >= 5.5) return 'text-amber-300'
  return 'text-red-300'
}

export function positionTone(position) {
  return {
    GK: 'bg-amber-400/10 text-amber-300 ring-amber-400/20',
    DEF: 'bg-sky-400/10 text-sky-300 ring-sky-400/20',
    MID: 'bg-lime/10 text-lime ring-lime/20',
    ATT: 'bg-rose-400/10 text-rose-300 ring-rose-400/20'
  }[position] || 'bg-white/5 text-slate-300 ring-white/10'
}

export function ordinal(number) {
  const value = Number(number)
  const suffix = value % 10 === 1 && value !== 11 ? 'st' : value % 10 === 2 && value !== 12 ? 'nd' : value % 10 === 3 && value !== 13 ? 'rd' : 'th'
  return `${value}${suffix}`
}

export function clamp(value, min, max) {
  return Math.min(max, Math.max(min, value))
}

export function formPercent(value) {
  return clamp(Math.round(Number(value) || 0), 0, 100)
}

export function ordinalSuffix(number) {
  return ordinal(number)
}

import { getFormation } from '../../shared/formations.js'

function roleScore(role, player) {
  const overall = Number(player.overall_rating || 70)
  const pace = Number(player.pace ?? overall)
  const shooting = Number(player.shooting ?? overall)
  const passing = Number(player.passing ?? overall)
  const dribbling = Number(player.dribbling ?? overall)
  const defending = Number(player.defending ?? overall)
  const physical = Number(player.physical ?? overall)

  if (role === 'GK') return overall
  if (role === 'CB') return overall * 0.7 + (defending * 0.5 + physical * 0.35 + pace * 0.15) * 0.3
  if (['LB', 'RB', 'LWB', 'RWB'].includes(role)) {
    return overall * 0.72 + (pace * 0.35 + defending * 0.3 + passing * 0.2 + physical * 0.15) * 0.28
  }
  if (role === 'DM') return overall * 0.72 + (defending * 0.45 + passing * 0.3 + physical * 0.25) * 0.28
  if (role === 'AM') return overall * 0.7 + (passing * 0.4 + dribbling * 0.3 + shooting * 0.3) * 0.3
  if (role === 'CM') return overall * 0.72 + (passing * 0.38 + dribbling * 0.22 + defending * 0.2 + physical * 0.2) * 0.28
  if (['LW', 'RW'].includes(role)) {
    return overall * 0.7 + (pace * 0.34 + dribbling * 0.32 + shooting * 0.22 + passing * 0.12) * 0.3
  }
  if (role === 'ST') return overall * 0.7 + (shooting * 0.45 + pace * 0.2 + physical * 0.2 + dribbling * 0.15) * 0.3
  return overall
}

export function selectXI(players, formationId = '4-3-3') {
  const formation = getFormation(formationId)
  const pool = [...players]
  const lineup = []

  for (const slot of formation.slots) {
    let candidates = pool.filter(player => player.position === slot.position)
    if (!candidates.length) candidates = [...pool]
    candidates.sort((a, b) => roleScore(slot.role, b) - roleScore(slot.role, a))
    const player = candidates[0]
    if (!player) break
    pool.splice(pool.indexOf(player), 1)
    lineup.push({ ...player, slot: slot.role, x: slot.x, y: slot.y })
  }

  return {
    formation,
    lineup,
    bench: pool.sort((a, b) => b.overall_rating - a.overall_rating)
  }
}

export function projectedStrength(players, formationId, style, tempo) {
  const { lineup } = selectXI(players, formationId)
  if (!lineup.length) return { attack: 50, defence: 50, overall: 50 }
  const group = position => {
    const rows = lineup.filter(player => player.position === position)
    if (!rows.length) return 70
    return rows.reduce((sum, player) => sum + player.overall_rating, 0) / rows.length
  }
  const gk = group('GK')
  const def = group('DEF')
  const mid = group('MID')
  const att = group('ATT')
  const tempoShift = (Number(tempo) - 3) * 1.2
  const attack = att * 0.58 + mid * 0.42 + (style?.attack || 0) + tempoShift
  const defence = def * 0.58 + gk * 0.42 + (style?.defence || 0) - tempoShift * 0.6
  return {
    attack: Math.round(attack * 10) / 10,
    defence: Math.round(defence * 10) / 10,
    overall: Math.round((gk * 0.16 + def * 0.3 + mid * 0.3 + att * 0.24) * 10) / 10
  }
}

import { createContext, useCallback, useContext, useEffect, useMemo, useRef, useState } from 'react'
import { api } from '../api'

const GameContext = createContext(null)

const VIEW_KEY = 'touchline:view'

export const VIEWS = [
  { id: 'dashboard', label: 'Dashboard', eyebrow: 'Club overview' },
  { id: 'squad', label: 'Squad', eyebrow: 'First team' },
  { id: 'tactics', label: 'Tactics', eyebrow: 'Game model' },
  { id: 'matchday', label: 'Match Day', eyebrow: 'Live match' },
  { id: 'transfers', label: 'Transfer Market', eyebrow: 'Recruitment' },
  { id: 'facilities', label: 'Facilities', eyebrow: 'Club infrastructure' },
  { id: 'league', label: 'League', eyebrow: 'Standings & fixtures' }
]

export function GameProvider({ children }) {
  const [data, setData] = useState(null)
  const [loading, setLoading] = useState(true)
  const [refreshing, setRefreshing] = useState(false)
  const [error, setError] = useState(null)
  const [toasts, setToasts] = useState([])
  const [playerModal, setPlayerModal] = useState(null)
  const [view, setViewState] = useState(() => {
    const saved = localStorage.getItem(VIEW_KEY)
    return VIEWS.some(item => item.id === saved) ? saved : 'dashboard'
  })
  const mounted = useRef(true)
  const toastTimers = useRef(new Map())

  useEffect(() => {
    mounted.current = true
    return () => {
      mounted.current = false
      toastTimers.current.forEach(timer => clearTimeout(timer))
    }
  }, [])

  const notify = useCallback((message, tone = 'success') => {
    const id = `${Date.now()}-${Math.random().toString(16).slice(2)}`
    setToasts(current => [...current.slice(-2), { id, message, tone }])
    const timer = setTimeout(() => {
      setToasts(current => current.filter(toast => toast.id !== id))
      toastTimers.current.delete(id)
    }, 4800)
    toastTimers.current.set(id, timer)
  }, [])

  const dismissToast = useCallback(id => {
    setToasts(current => current.filter(toast => toast.id !== id))
    const timer = toastTimers.current.get(id)
    if (timer) clearTimeout(timer)
    toastTimers.current.delete(id)
  }, [])

  const refresh = useCallback(async ({ silent = false } = {}) => {
    if (!silent) setLoading(true)
    else setRefreshing(true)
    try {
      const payload = await api.bootstrap()
      if (!mounted.current) return payload
      setData(payload)
      setError(null)
      return payload
    } catch (err) {
      if (mounted.current) setError(err)
      if (!silent) notify(err.message || 'Could not load your club.', 'error')
      return null
    } finally {
      if (mounted.current) {
        setLoading(false)
        setRefreshing(false)
      }
    }
  }, [notify])

  useEffect(() => {
    refresh()
  }, [refresh])

  const setView = useCallback(id => {
    if (!VIEWS.some(item => item.id === id)) return
    setViewState(id)
    localStorage.setItem(VIEW_KEY, id)
    window.scrollTo({ top: 0, behavior: 'smooth' })
  }, [])

  const purchasePlayer = useCallback(async playerId => {
    try {
      const result = await api.buyPlayer(playerId, data?.user?.id)
      notify(result.message, 'success')
      await refresh({ silent: true })
      return result
    } catch (err) {
      notify(err.message || 'The transfer could not be completed.', 'error')
      throw err
    }
  }, [data?.user?.id, notify, refresh])

  const upgradeFacility = useCallback(async facility => {
    try {
      const result = await api.upgradeFacility(data?.user?.id, facility)
      notify(result.message, 'success')
      await refresh({ silent: true })
      return result
    } catch (err) {
      notify(err.message || 'Upgrade failed.', 'error')
      throw err
    }
  }, [data?.user?.id, notify, refresh])

  const updateTactics = useCallback(async tactics => {
    try {
      const result = await api.updateTactics(data?.user?.id, tactics)
      notify(result.message, 'success')
      await refresh({ silent: true })
      return result
    } catch (err) {
      notify(err.message || 'Could not save tactics.', 'error')
      throw err
    }
  }, [data?.user?.id, notify, refresh])

  const simulateMatch = useCallback(async matchId => {
    try {
      return await api.simulateMatch(matchId)
    } catch (err) {
      notify(err.message || 'The match could not be simulated.', 'error')
      throw err
    }
  }, [notify])

  const openPlayer = useCallback((player, options = {}) => {
    setPlayerModal({ player, ...options })
  }, [])

  const closePlayer = useCallback(() => setPlayerModal(null), [])

  const value = useMemo(() => ({
    data,
    loading,
    refreshing,
    error,
    toasts,
    view,
    setView,
    refresh,
    notify,
    dismissToast,
    purchasePlayer,
    upgradeFacility,
    updateTactics,
    simulateMatch,
    playerModal,
    openPlayer,
    closePlayer
  }), [
    data, loading, refreshing, error, toasts, view, setView, refresh, notify, dismissToast,
    purchasePlayer, upgradeFacility, updateTactics, simulateMatch, playerModal, openPlayer, closePlayer
  ])

  return <GameContext.Provider value={value}>{children}</GameContext.Provider>
}

export function useGame() {
  const context = useContext(GameContext)
  if (!context) throw new Error('useGame must be used inside GameProvider')
  return context
}

