              key={`goal-${latestEvent.minute}`}
              initial={{ opacity: 0, scale: 0.7 }}
              animate={{ opacity: [0, 1, 1, 0], scale: [0.7, 1.08, 1.08, 1.2] }}
              exit={{ opacity: 0 }}
              transition={{ duration: 1.8, times: [0, 0.18, 0.7, 1] }}
